<script setup lang="ts">
import {computed} from 'vue'
import type {TripDay,ItineraryItem} from '@/types'
import {orderedActivities,timeLabel,overlapping} from '@/composables/tripPlanner'
const props=defineProps<{days:TripDay[];items:ItineraryItem[];busy:boolean}>()
const emit=defineEmits<{add:[date:string];edit:[item:ItineraryItem];options:[item:ItineraryItem];reorder:[day:string,from:string,to:string]}>()
const groups=computed(()=>{
 const groups=new Map<string,ItineraryItem[]>()
 for(const item of props.items){const day=props.days.find(d=>d.id===item.trip_day_id);const key=day?.is_ideas?'':day?.date||'';groups.set(key,[...(groups.get(key)||[]),item])}
 return [...groups].sort(([a],[b])=>a&&b?a.localeCompare(b):a?-1:b?1:0).map(([date,items])=>({date,items:orderedActivities(items)}))
})
const overlaps=computed(()=>overlapping(props.items,props.days))
function dateTitle(date:string){return date?new Date(date+'T12:00:00').toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'}):'Unscheduled'}
function neighbor(item:ItineraryItem,delta:number){const rows=groups.value.find(g=>g.items.some(i=>i.id===item.id))!.items.filter(i=>!i.scheduled_time);return rows[rows.findIndex(i=>i.id===item.id)+delta]}
</script>
<template><section class="folder-itinerary" aria-label="Places in your trip">
 <div v-if="!items.length" class="folder-empty"><span class="empty-stamp" aria-hidden="true">↗</span><p class="eyebrow">Your trip, one place at a time</p><h2>Start somewhere lovely.</h2><p>A café, a viewpoint, or a little time to wander.<br>Dates and times can come later.</p><button class="primary" :disabled="busy" @click="emit('add','')">Add your first place</button></div>
 <section v-for="group in groups" :key="group.date" class="date-section"><header><div><p class="eyebrow">{{group.date?'A day to explore':'Room for possibilities'}}</p><h2>{{dateTitle(group.date)}}</h2></div><span class="place-count">{{group.items.length}} {{group.items.length===1?'place':'places'}}</span></header>
 <ol class="stop-list"><li v-for="item in group.items" :key="item.id" class="stop"><div class="stop-time">{{timeLabel(item)}}</div><article class="stop-ticket"><div class="stop-top"><h3><button @click="emit('edit',item)" :disabled="busy">{{item.title}}</button></h3><button class="stop-menu" :aria-label="'Options for '+item.title" :disabled="busy" @click="emit('options',item)">•••</button></div><p v-if="item.location_name" class="stop-address">{{item.location_name}}</p><p v-if="item.description" class="stop-notes">{{item.description}}</p><p v-if="overlaps.has(item.id)" class="overlap-note">Overlaps another plan · keep both if intended.</p><div class="stop-actions"><button :disabled="busy" @click="emit('edit',item)">Edit place</button><button :disabled="busy" @click="emit('edit',item)">Move date</button><template v-if="!item.scheduled_time"><button :disabled="busy||!neighbor(item,-1)" :aria-label="'Move '+item.title+' up'" @click="emit('reorder',item.trip_day_id,item.id,neighbor(item,-1)!.id)">↑</button><button :disabled="busy||!neighbor(item,1)" :aria-label="'Move '+item.title+' down'" @click="emit('reorder',item.trip_day_id,item.id,neighbor(item,1)!.id)">↓</button></template></div></article></li></ol>
 <button class="add-next" :disabled="busy" @click="emit('add',group.date)">＋ Add another place</button></section>
</section></template>
<style scoped>
.folder-itinerary{padding-bottom:max(36px,env(safe-area-inset-bottom))}.folder-empty{padding:46px 20px;text-align:center;background:#f5f0e4;border-radius:14px}.empty-stamp{display:inline-grid;place-items:center;border:1px dashed #9ba68b;color:#748067;border-radius:50%;width:58px;height:58px;font-size:32px;transform:rotate(-12deg);margin-bottom:20px}.folder-empty h2{font-size:32px;margin:10px 0}.folder-empty p{line-height:1.7;color:#7d7365}.folder-empty button{margin-top:24px}.date-section{margin:12px 0 32px}.date-section>header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 18px}.date-section h2{font-size:25px;margin:6px 0}.place-count{color:#7d7365;font-size:12px;white-space:nowrap}.stop-list{list-style:none;padding:0;margin:0 0 0 7px;border-left:1px solid #b5bda8}.stop{position:relative;padding:0 0 18px 20px}.stop:before{content:'';position:absolute;left:-5px;top:7px;width:9px;height:9px;background:#879476;border:2px solid #faf6ed;border-radius:50%}.stop-time{font-size:13px;font-weight:600;color:#74283c;font-variant-numeric:tabular-nums;margin-bottom:9px}.stop-ticket{background:#fffaf0;border:1px solid #e3dac8;border-left:3px solid #a3af92;border-radius:3px 12px 12px 3px;padding:8px 16px 10px;box-shadow:0 3px 10px #51412c04;min-width:0}.stop-top{display:flex;align-items:start;gap:8px}.stop-top h3{flex:1;min-width:0;margin:0}.stop-top h3 button{font:24px/1.2 'Crimson Text',Georgia,serif;text-align:left;padding:8px 0;border:0;background:transparent;overflow-wrap:anywhere;display:block}.stop-menu{border:0;background:transparent;min-width:44px;padding:0;letter-spacing:2px}.stop-address{font-size:14px;color:#727c65;line-height:1.5;overflow-wrap:anywhere;margin:0 0 8px}.stop-notes{font-size:14px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin:6px 0}.stop-actions{display:flex;gap:4px;flex-wrap:wrap;border-top:1px dashed #ded3bf;margin-top:10px;padding-top:4px}.stop-actions button{font-size:12px;border:0;background:transparent;padding:8px 10px;min-width:44px;min-height:44px}.stop-actions button:first-child{padding-left:0}.overlap-note{font-size:12px;color:#8a633d;line-height:1.5}.add-next{border-style:dashed;background:transparent;margin-left:27px;width:calc(100% - 27px);color:#74283c}.date-section .eyebrow{font-size:10px}@media(min-width:760px){.stop{display:grid;grid-template-columns:130px minmax(0,1fr);gap:10px}.stop:before{top:20px}.stop-time{padding-top:15px}.stop-ticket{padding:12px 20px}.date-section h2{font-size:28px}.add-next{margin-left:167px;width:calc(100% - 167px)}}
</style>
